const staticData = $getWorkflowStaticData('global');
const runId = $node['Normalize + Validate Input'].json.runId;
const run = staticData.runs?.[runId];
if (!run) return [];

const already = new Set((run.docs||[]).map(d=>d.url));
const allHarvested = (run._harvested || []).filter(u=>!already.has(u));

// STRATEGY: Bypass OCR.Space (unreliable free key, times out on large scanned PDFs).
// Instead, store PDF URLs directly in run.docs with has_text=true and pdfUrl field.
// They will be sent to Claude via URL-based document API in the extraction stage.
const isPdf = u => u.toLowerCase().endsWith('.pdf');
const pdfUrls = allHarvested.filter(isPdf);
const htmlUrls = allHarvested.filter(u => !isPdf(u));

// Store PDFs directly in run.docs (skip OCR, Claude reads them by URL)
const maxPdfs = run.isPremium ? 20 : 10;
const pdfBatch = pdfUrls.slice(0, maxPdfs);

if (pdfBatch.length > 0) {
  run.docs = run.docs || [];
  for (const u of pdfBatch) {
    run.docs.push({
      url: u,
      kind: 'pdf',
      fetched_at: new Date().toISOString(),
      text_preview: '',
      has_text: true,
      pdfUrl: u,
      harvested: true
    });
  }
  run.logs.push({t: new Date().toISOString(), m: `Queued ${pdfBatch.length} PDFs for Claude URL-based extraction (bypassing OCR)` });
}

// Only send HTML URLs through the 2nd-pass fetch loop
const maxHtml = run.isPremium ? 20 : 8;
const htmlBatch = htmlUrls.slice(0, maxHtml);

run.progress = Math.max(run.progress, 56);
run.logs.push({t:new Date().toISOString(), m:`2nd-pass: ${pdfBatch.length} PDFs direct + ${htmlBatch.length} HTML to fetch`});

// If no HTML to fetch, skip the harvest loop
if (htmlBatch.length === 0) {
  run.logs.push({t:new Date().toISOString(), m:'No HTML to harvest, proceeding to extraction'});
  return [{ json: { runId, _skipHarvest: true } }];
}

return htmlBatch.map(url => ({
  runId,
  localityName: run.localityName,
  dateFrom: run.dateFrom,
  dateTo: run.dateTo,
  isPremium: run.isPremium,
  url,
  kind: 'html'
}));
